fn monotonic(l: [int]) -> bool:
    if len(l) <= 1:
        return True

    var increasing = None
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            if increasing is None:
                increasing = True
            elif not increasing:
                return False
        elif l[i] < l[i - 1]:
            if increasing is None:
                increasing = False
            elif increasing:
                return False

    return True

