fn separate_paren_groups(paren_string: str) -> [str]:
    var result = []
    var stack = []
    var current = ""
    for c in paren_string:
        if c == ' ':
            continue
        if c == '(':
            stack.append(c)
            current += c
        elif c == ')':
            stack.pop()
            current += c
            if len(stack) == 0:
                result.append(current)
                current = ""
    return result

def separate_paren_groups(paren_string: str) -> list[str]:
    result = []
    current_group = []
    depth = 0

    for char in paren_string.replace(" ", ""):
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1

        current_group.append(char)

        if depth == 0:
            result.append("".join(current_group))
            current_group = []

    return result

