fn rolling_max(numbers: [int]) -> [int]:
    var result = []
    var max_so_far = None
    for n in numbers:
        if max_so_far is None or n > max_so_far:
            max_so_far = n
        result.append(max_so_far)
    return result

fn choose_num(x: int, y: int) -> int:
    if x > y:
        return -1
    if y % 2 == 0:
        return y
    if (y - 1) >= x:
        return y - 1
    return -1

def encode(message: str) -> str:
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    shifted_vowels = {v: chr((ord(v) - 97 + 2) % 26 + 97) for v in vowels}
    shifted_vowels.update({v.upper(): shifted_vowels[v].upper() for v in vowels})

    def swap_case_and_shift_vowel(char: str) -> str:
        if char.isalpha():
            if char.lower() in shifted_vowels:
                return shifted_vowels[char]
            else:
                return char.swapcase()
        return char

    return ''.join(swap_case_and_shift_vowel(c) for c in message)

