type PrimeFibResult = Ok(int) | Err(str)

fn is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

fn prime_fib(n: int) -> int ! PrimeFibResult:
    if n <= 0:
        return Err("n must be a positive integer")
    var count = 0
    var a = 0
    var b = 1
    while True:
        var next_fib = a + b
        a = b
        b = next_fib
        if is_prime(next_fib):
            count += 1
            if count == n:
                return Ok(next_fib)

