fn max_fill(grid: [[int]], capacity: int) -> int:
    var rows = len(grid)
    var cols = len(grid[0])
    var buckets = [0] * rows
    var total_drops = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                buckets[i] += 1

    for i in range(rows):
        while buckets[i] > 0:
            buckets[i] -= capacity
            total_drops += 1

    return total_drops

