type Memo[T](items: [T])

impl Memo[T]:
    fn new() -> Memo[T]:
        return Memo([None] * 1000)

    fn get(self, i: int) -> T?:
        return self.items[i]

    fn set(inout self, i: int, v: T):
        self.items[i] = v

fn fibfib(n: int) -> int:
    var memo = Memo[int]()
    memo.set(0, 0)
    memo.set(1, 0)
    memo.set(2, 1)

    fn fibfib_helper(n: int) -> int:
        if memo.get(n) is not None:
            return memo.get(n)
        else:
            var result = fibfib_helper(n - 1) + fibfib_helper(n - 2) + fibfib_helper(n - 3)
            memo.set(n, result)
            return result

    return fibfib_helper(n)

