type Heap[int](items: [int])

impl Heap[int]:
    fn push(inout self, item: int):
        self.items.append(item)
        self._bubble_up(len(self.items) - 1)

    fn pop_min(inout self) -> int?:
        if len(self.items) == 0:
            return None
        if len(self.items) == 1:
            return self.items.pop()
        min_item = self.items[0]
        self.items[0] = self.items.pop()
        self._bubble_down(0)
        return min_item

    fn peek(inout self) -> int?:
        if len(self.items) == 0:
            return None
        return self.items[0]

    fn _bubble_up(inout self, index: int):
        while index > 0:
            parent_index = (index - 1) // 2
            if self.items[index] < self.items[parent_index]:
                self.items[index], self.items[parent_index] = self.items[parent_index], self.items[index]
                index = parent_index
            else:
                break

    fn _bubble_down(inout self, index: int):
        while True:
            left_child_index = 2 * index + 1
            right_child_index = 2 * index + 2
            smallest_index = index

            if left_child_index < len(self.items) and self.items[left_child_index] < self.items[smallest_index]:
                smallest_index = left_child_index

            if right_child_index < len(self.items) and self.items[right_child_index] < self.items[smallest_index]:
                smallest_index = right_child_index

            if smallest_index != index:
                self.items[index], self.items[smallest_index] = self.items[smallest_index], self.items[index]
                index = smallest_index
            else:
                break

fn heap_sort(iterable: [int]) -> [int]:
    heap = Heap[int](items=[])
    for item in iterable:
        heap.push(item)
    sorted_list: [int] = []
    while True:
        item = heap.pop_min()
        if item is None:
            break
        sorted_list.append(item)
    return sorted_list

