def sum_div(number: int) -> int:
    """
    Write a function to return the sum of all divisors of a number.
    """
    if number <= 0:
        raise ValueError("Number must be greater than 0")

    divisors = [1]
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            divisors.append(i)
            if i != number // i:
                divisors.append(number // i)

    return sum(divisors)

